{
     "title": "CSCI-632: Mobile Robot Programming - Foundations Lesson Blueprint",
     "learningObjectives": [
       "Define the core software architecture components required for mobile robot programming, including reactive control loops and modular design patterns.",
       "Explain how reactive motion control algorithms process sensor data to generate real-time navigation commands.",
       "Demonstrate the integration of map building and localization techniques to enable autonomous path planning in dynamic environments."
     ],
     "beats": [
       {
         "title": "Lesson Introduction and Course Scope",
         "claim": "CSCI-632 focuses on standard and novel techniques for mobile robot programming, including software architectures, reactive motion control, map building, localization, and path pl",
         "example": "Students will implement various algorithms in simulation as well as on a real robot, and investigate and report on current research in the area.",
         "visualDirection": "Display a slide with the course title, duration (8-12 minutes), and a simple diagram showing the four main modules: Software Architecture, Reactive Motion Control, Map Building/Localization, and Path Planning.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Software Architecture Fundamentals",
         "claim": "Mobile robot programming relies on modular software architectures that separate perception, planning, and control systems to ensure maintainability and scalability.",
         "example": "A typical architecture uses a central controller that routes data between independent modules, allowing each component to be updated without disrupting the entire system.",
         "visualDirection": "Show a block diagram with four labeled blocks: Sensor Input, Perception, Planning, and Actuation, connected by data flow arrows.",
         "sourceIds": ["rit-csci-632"]
       },
       {

       "title": "Reactive Motion Control Basics",
       "claim": "Reactive motion control processes real-time sensor data to generate immediate navigation commands without requiring a complete global map.",
       "example": "When an obstacle is detected, the robot adjusts its heading and speed instantly using a rule-based response function rather than recalculating a full path.",
         "visualDirection": "Illustrate a simple feedback loop showing sensor input -> decision logic -> motor command, with a note highlighting 'reactive' vs 'planning' control.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Map Building Techniques",
         "claim": "Map building algorithms construct environmental representations by fusing sensor observations with existing spatial data to create navigable models.",
         "example": "Laser scanners record distance measurements that are triangulated to populate a grid-based map, which is then updated as the robot moves.",
         "visualDirection": "Display a side-by-side comparison of a blank grid and a populated grid with distance markers, showing how sensor data fills in spatial information.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Localization Methods",
         "claim": "Localization determines the robot's current position within a map by matching observed features to stored environmental data.",
         "example": "The robot compares its camera feed to a pre-mapped image bank and calculates the best match to pinpoint its coordinates.",
         "visualDirection": "Show a small inset of a map with a moving robot icon, highlighting the 'current position' and 'matched features' with connecting lines.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Path Planning Algorithms",
         "claim": "Path planning generates optimal sequences of actions that guide the robot from a start point to a goal while avoiding obstacles.",
         "example": "A search algorithm explores possible routes, pruning dead ends and selecting the shortest path based on distance and energy constraints.",
         "visualDirection": "Render a top-down map with a start point, goal, and multiple route options, highlighting the selected path in a distinct color.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Simulation vs. Real Robot Testing",
         "claim": "Students implement algorithms in both simulation environments and on physical robots to validate performance under controlled and real-world conditions.",
         "example": "A navigation routine is first tested in a virtual environment to debug code, then deployed on a wheeled robot to measure real-time response times.",
         "visualDirection": "Split screen showing a simulation interface on the left and a photo of a real robot on the right, with a checkmark indicating successful deployment.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Research Investigation and Reporting",
         "claim": "Students investigate current research in mobile robot programming to identify emerging techniques and contribute to the field through structured reports.",
         "example": "A student analyzes a recent paper on dynamic path planning, summarizes key findings, and proposes a modification for classroom implementation.",
         "visualDirection": "Display a template for a research report with sections for 'Summary', 'Key Findings', and 'Proposed Modifications', using placeholder text.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Prerequisites and Course Logistics",
         "claim": "The course requires prior knowledge from CSCI-630 or CSCI-331 and is typically offered every other year during the spring semester.",
         "example": "Students must have completed foundational programming courses before enrolling, ensuring they possess the necessary technical background.",
         "visualDirection": "List the prerequisites and schedule details in a clean, bulleted format on a slide, with icons for a book and a calendar.",
         "sourceIds": ["rit-csci-632"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students will evaluate their implementations against a checklist that verifies software architecture, motion control responsiveness, map accuracy, and path planning efficiency.",
         "example": "The checklist includes items like 'Modular code structure verified', 'Reactive response time < 100ms', 'Map update frequency consistent', and 'Path deviation within tolerance'.",
         "visualDirection": "Show a simple checklist graphic with four boxes, each containing a key metric and a pass/fail indicator, ready for student annotation.",
         "sourceIds": ["rit-csci-632"]
       }
     ]
   }
